function modal(title,body,{wide=false,submitLabel='Guardar',onSubmit}={}){const root=document.querySelector('#modal-root');root.innerHTML=`<div class="modal-backdrop"><section role="dialog" aria-modal="true" aria-labelledby="modal-heading" class="modal ${wide?'wide':''}"><header class="modal-head"><h2 id="modal-heading">${title}</h2><button class="icon-btn" type="button" aria-label="Cerrar" data-close>✕</button></header><form id="modal-form"><div class="modal-body">${body}</div><footer class="modal-foot"><button class="btn" type="button" data-close>Cancelar</button>${onSubmit?`<button class="btn primary" type="submit" id="modal-submit">${submitLabel}</button>`:''}</footer></form></section></div>`;root.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>root.innerHTML='');root.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))root.innerHTML=''};for(const button of root.querySelectorAll('button:not([type])'))button.type='button';const form=root.querySelector('#modal-form');if(!onSubmit)form.onsubmit=e=>e.preventDefault();if(onSubmit)form.onsubmit=async e=>{e.preventDefault();const b=root.querySelector('#modal-submit');b.disabled=true;b.textContent='Guardando…';try{await onSubmit(new FormData(form));if(root.contains(form))root.innerHTML=''}catch(err){notify(errText(err),true);b.disabled=false;b.textContent=submitLabel}};root.onkeydown=e=>{if(e.key==='Escape'){root.innerHTML='';return;}if(e.key==='Tab'){const controls=[...root.querySelectorAll('button,input,select,textarea,summary')].filter(x=>!x.disabled&&x.getClientRects().length);const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}};root.querySelector('input,select,textarea,button')?.focus();return root;}
